# 6) Restart behavior now targets coordinator state and lifecycle owner directly.
write(
    "tests/test_restart_state_runtime.py",
    '''from __future__ import annotations\n\nimport asyncio\nimport os\nfrom concurrent.futures import Future\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nfrom services import bot_lifecycle\nfrom services import livedub_delivery_coordinator as delivery\nfrom services import operator_runtime_status as operator_status\nfrom services import restart_state_runtime as restart\n\n\ndef test_reset_releases_inflight_but_preserves_confirmed_success() -> None:\n    pending = Future()\n    pending_key = ("new", "chat", "reply", "pending")\n    success_key = ("new", "chat", "reply", "success")\n    with delivery._COMPANION_LOCK:\n        delivery._COMPANION_INFLIGHT.clear()\n        delivery._COMPANION_SENT.clear()\n        delivery._COMPANION_INFLIGHT[pending_key] = pending\n        delivery._COMPANION_SENT[success_key] = 123.0\n\n    assert restart._reset_audio_coalescing() == 1\n    assert pending.result(timeout=0) is False\n    assert pending_key not in delivery._COMPANION_INFLIGHT\n    assert success_key in delivery._COMPANION_SENT\n\n    with delivery._COMPANION_LOCK:\n        delivery._COMPANION_INFLIGHT.clear()\n        delivery._COMPANION_SENT.clear()\n\n\ndef test_process_crash_cleanup_deletes_only_stale_deferred_files(tmp_path: Path) -> None:\n    root = tmp_path / "mp3bot_livedub_deferred"\n    root.mkdir()\n    stale = root / "stale.mp3"\n    recent = root / "recent.mp3"\n    stale.write_bytes(b"old")\n    recent.write_bytes(b"new")\n    now = 1_000_000.0\n    os.utime(stale, (now - 7 * 3600, now - 7 * 3600))\n    os.utime(recent, (now - 60, now - 60))\n    assert restart.cleanup_orphaned_deferred_files(max_age_hours=6, root=root, now=now) == 1\n    assert not stale.exists()\n    assert recent.exists()\n\n\ndef test_process_lifecycle_resets_before_async_runner(monkeypatch) -> None:\n    order: list[str] = []\n\n    async def runner():\n        order.append("run")\n        return None\n\n    stub = SimpleNamespace(run_bot_async=runner)\n    monkeypatch.setattr(bot_lifecycle, "_start_health_thread", lambda _module: None)\n    monkeypatch.setattr(\n        restart,\n        "reset_cross_loop_state",\n        lambda: order.append("reset") or {\n            "audio_inflight": 0, "deferred_source": 0, "companion_marks": 0, "orphan_files": 0\n        },\n    )\n    assert bot_lifecycle.run_bot_process(stub) == 0\n    assert order == ["reset", "run"]\n\n\ndef test_restart_installer_does_not_replace_bot_runner(monkeypatch) -> None:\n    async def runner():\n        return None\n\n    async def status_command(update, context):\n        del update, context\n        return None\n\n    stub = SimpleNamespace(run_bot_async=runner, status_command=status_command)\n    original_runner = stub.run_bot_async\n    monkeypatch.setattr(restart, "_INSTALLED", False)\n    monkeypatch.setattr(operator_status, "_INSTALLED", False)\n    restart.install_restart_state_runtime(stub)\n    assert stub.run_bot_async is original_runner\n    assert getattr(stub.status_command, "_mp3bot_operator_runtime_status") is True\n''',
)

# 7) Cache recovery tests its real persistence API, no installation shim.
write(
    "tests/test_livedub_audio_cache_recovery.py",
    '''from __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport pytest\n\nfrom services import livedub_audio_cache_recovery as recovery\n\n\ndef _write(path: Path, data) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")\n\n\ndef test_corrupt_primary_recovers_valid_backup_and_repairs_disk(tmp_path: Path) -> None:\n    path = tmp_path / "cache.json"\n    backup = path.with_suffix(path.suffix + ".bak")\n    expected = {"video-old": {"saved_at": 1}}\n    path.write_text("{broken", encoding="utf-8")\n    _write(backup, expected)\n    assert recovery.load_recoverable_cache(path) == expected\n    assert json.loads(path.read_text(encoding="utf-8")) == expected\n\n\ndef test_successful_save_keeps_previous_valid_generation_in_backup(tmp_path: Path) -> None:\n    path = tmp_path / "cache.json"\n    backup = path.with_suffix(path.suffix + ".bak")\n    old = {"video-old": {"saved_at": 1}}\n    new = {"video-new": {"saved_at": 2}}\n    _write(path, old)\n    recovery.save_recoverable_cache(path, new)\n    assert json.loads(path.read_text(encoding="utf-8")) == new\n    assert json.loads(backup.read_text(encoding="utf-8")) == old\n\n\n@pytest.mark.parametrize("mode", ["corrupt", "wrong", "noop"])\ndef test_invalid_new_generation_rolls_back_previous_cache(tmp_path: Path, monkeypatch, mode: str) -> None:\n    path = tmp_path / "cache.json"\n    backup = path.with_suffix(path.suffix + ".bak")\n    old = {"video-old": {"saved_at": 1}}\n    wanted = {"video-new": {"saved_at": 2}}\n    _write(path, old)\n\n    def broken(target: Path, data):\n        if mode == "corrupt":\n            target.write_text("not-json", encoding="utf-8")\n        elif mode == "wrong":\n            _write(target, {"wrong": {"saved_at": 99}})\n        else:\n            return None\n\n    monkeypatch.setattr(recovery, "_atomic_write", broken)\n    with pytest.raises(RuntimeError, match="differs from requested generation"):\n        recovery.save_recoverable_cache(path, wanted)\n    assert json.loads(path.read_text(encoding="utf-8")) == old\n    assert json.loads(backup.read_text(encoding="utf-8")) == old\n\n\ndef test_wrong_generation_without_backup_is_discarded(tmp_path: Path, monkeypatch) -> None:\n    path = tmp_path / "cache.json"\n    monkeypatch.setattr(recovery, "_atomic_write", lambda target, data: _write(target, {"wrong": {"saved_at": 9}}))\n    with pytest.raises(RuntimeError):\n        recovery.save_recoverable_cache(path, {"wanted": {"saved_at": 10}})\n    assert not path.exists()\n\n\ndef test_recovered_cache_is_preserved_when_companion_adds_variant(tmp_path: Path, monkeypatch) -> None:\n    import services.livedub_audio_companion as companion\n\n    path = tmp_path / "cache.json"\n    backup = path.with_suffix(path.suffix + ".bak")\n    old = {\n        "old-video": {\n            "schema_version": 2, "saved_at": 1,\n            "variants": {"clean": {"audio_file_id": "old-clean"}, "mixed": {"audio_file_id": "old-mixed"}},\n        }\n    }\n    path.write_text("{damaged", encoding="utf-8")\n    _write(backup, old)\n    monkeypatch.setattr(companion, "_cache_path", lambda: path)\n    companion._cache_put_variant("new-video", "clean", "new-clean", title="New")\n    saved = json.loads(path.read_text(encoding="utf-8"))\n    assert saved["old-video"]["variants"]["mixed"]["audio_file_id"] == "old-mixed"\n    assert saved["new-video"]["variants"]["clean"]["audio_file_id"] == "new-clean"\n\n\ndef test_expected_generation_keeps_newest_500() -> None:\n    data = {f"video-{idx}": {"saved_at": idx} for idx in range(510)}\n    expected = recovery._expected_generation(data)\n    assert len(expected) == 500\n    assert "video-509" in expected and "video-10" in expected\n    assert "video-9" not in expected\n\n\ndef test_bounded_reader_rejects_oversized_or_non_object_json(tmp_path: Path) -> None:\n    oversized = tmp_path / "oversized.json"\n    oversized.write_text(json.dumps({"x": "a" * 200}), encoding="utf-8")\n    assert recovery._read_mapping(oversized, max_bytes=32) is None\n    array = tmp_path / "array.json"\n    array.write_text("[]", encoding="utf-8")\n    assert recovery._read_mapping(array) is None\n''',
)

# 8) Provenance tests producer/consumer helpers directly.
write(
    "tests/test_livedub_ru_provenance.py",
    '''from __future__ import annotations\n\nimport json\nimport os\nfrom pathlib import Path\n\nimport pytest\n\nfrom services import livedub_ru_provenance as provenance\n\n\ndef _audio(path: Path, payload: bytes = b"audio" * 500) -> Path:\n    path.write_bytes(payload)\n    return path\n\n\ndef test_atomic_marker_roundtrip_selects_exact_older_vot_file(tmp_path: Path) -> None:\n    exact = _audio(tmp_path / "video.live.mp3")\n    unrelated = _audio(tmp_path / "newer-unrelated.mp3", b"other" * 500)\n    os.utime(exact, (10, 10)); os.utime(unrelated, (20, 20))\n    assert provenance.write_ru_audio_provenance(exact, voice_style="live") is True\n    assert provenance.read_ru_audio_provenance(tmp_path) == exact\n    assert list(tmp_path.glob(".livedub_ru_audio.json.*.tmp")) == []\n\n\ndef test_marker_rejects_path_traversal_and_changed_files(tmp_path: Path) -> None:\n    exact = _audio(tmp_path / "video.live.mp3")\n    assert provenance.write_ru_audio_provenance(exact)\n    exact.write_bytes(b"changed" * 600)\n    assert provenance.read_ru_audio_provenance(tmp_path) is None\n    marker = tmp_path / ".livedub_ru_audio.json"\n    marker.write_text(json.dumps({"schema_version": 1, "filename": "../outside.mp3", "size_bytes": 1, "mtime_ns": 1}), encoding="utf-8")\n    assert provenance.read_ru_audio_provenance(tmp_path) is None\n\n\ndef test_symlinked_and_derived_audio_are_rejected(tmp_path: Path) -> None:\n    derived = _audio(tmp_path / "video.final-mix.mp3")\n    assert provenance.write_ru_audio_provenance(derived) is False\n    target = _audio(tmp_path.parent / "outside-target.mp3")\n    link = tmp_path / "translation.live.mp3"\n    try:\n        link.symlink_to(target)\n    except (OSError, NotImplementedError):\n        pytest.skip("symlink creation unavailable")\n    assert provenance.write_ru_audio_provenance(link) is False\n\n\ndef test_record_returned_ru_audio_accepts_only_current_changed_file(tmp_path: Path) -> None:\n    stale = _audio(tmp_path / "stale.live.mp3")\n    before = provenance.snapshot_ru_audio_candidates(tmp_path)\n    assert provenance.record_returned_ru_audio(stale, workdir=tmp_path, before=before) is False\n    fresh = _audio(tmp_path / "fresh.live.mp3", b"fresh" * 500)\n    assert provenance.record_returned_ru_audio(fresh, workdir=tmp_path, before=before, voice_style="live") is True\n    assert provenance.read_ru_audio_provenance(tmp_path) == fresh\n\n\ndef test_record_returned_ru_audio_rejects_outside_workdir(tmp_path: Path) -> None:\n    outside = _audio(tmp_path.parent / "outside-return.live.mp3")\n    assert provenance.record_returned_ru_audio(outside, workdir=tmp_path, before={}) is False\n    assert not (tmp_path / ".livedub_ru_audio.json").exists()\n\n\ndef test_mix_consumer_prefers_exact_provenance(tmp_path: Path) -> None:\n    from services import livedub_mix as mix\n\n    exact = _audio(tmp_path / "exact.live.mp3")\n    fallback = _audio(tmp_path / "fallback.mp3", b"fallback" * 500)\n    os.utime(exact, (10, 10)); os.utime(fallback, (20, 20))\n    assert provenance.write_ru_audio_provenance(exact)\n    _original, selected = mix.find_pro_tracks(tmp_path)\n    assert selected == exact\n''',
)

