write(
    "tests/test_livedub_quality_runtime.py",
    '''"""Regression contracts for Gemini quality policy and explicit LiveDub delivery."""\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport pytest\n\nfrom services import livedub_delivery_coordinator as delivery\nfrom services import livedub_quality_runtime as runtime\n\n\ndef _max_policy_source() -> str:\n    return Path("services/gemini_max_quality.py").read_text(encoding="utf-8")\n\n\ndef test_pre_main_manifest_owns_policy_before_core_clients() -> None:\n    package = Path("services/__init__.py").read_text(encoding="utf-8")\n    manifest = Path("services/runtime_manifest.py").read_text(encoding="utf-8")\n    owner = Path("services/pre_main_policy.py").read_text(encoding="utf-8")\n    assert "configure_gemini_policy()" not in package\n    assert '"pre-main-quality-policy"' in manifest\n    assert '"services.pre_main_policy"' in manifest\n    assert owner.index("configure_max_quality_env()") < owner.index("configure_gemini_policy()")\n    assert "configure_gemini_network()" in owner\n\n\ndef test_production_policy_keeps_semantic_work_on_36_high() -> None:\n    runtime.configure_gemini_policy()\n    for name in ("GEMINI_MODEL", "GEMINI_MAX_MODEL", "LIVEDUB_INFO_MODEL", "LIVEDUB_QUICK_QA_MODEL", "LIVEDUB_LONG_QA_MODEL", "LIVEDUB_QA_VERIFY_MODEL"):\n        assert runtime.os.environ[name] == "gemini-3.6-flash"\n    for name in ("GEMINI_FORCE_THINKING_LEVEL", "LIVEDUB_INFO_THINKING", "LIVEDUB_QUICK_QA_THINKING", "LIVEDUB_LONG_QA_THINKING", "LIVEDUB_QA_VERIFY_THINKING"):\n        assert runtime.os.environ[name] == "high"\n    assert runtime.os.environ["LIVEDUB_INFO_FALLBACK_MODELS"] == ""\n    assert runtime.os.environ["LIVEDUB_PUBLICATION_FALLBACK_MODELS"] == ""\n\n\ndef test_utility_route_is_35_family_without_semantic_fallback() -> None:\n    runtime.configure_gemini_policy()\n    assert runtime.os.environ["GEMINI_LIGHT_MODEL"] == "gemini-3.5-flash-lite"\n    assert runtime.os.environ["GEMINI_LIGHT_FALLBACK_MODELS"] == "gemini-3.5-flash"\n    assert runtime.os.environ["GEMINI_LIGHT_ALLOW_MAIN_FALLBACK"] == "0"\n    assert "gemini-3.1" not in _max_policy_source()\n    assert "gemini-2.5" not in _max_policy_source()\n\n\ndef test_user_visible_publication_uses_36_high_not_utility() -> None:\n    publication = Path("services/livedub_publication_core.py").read_text(encoding="utf-8")\n    assert '_PUBLICATION_MODEL = "gemini-3.6-flash"' in publication\n    assert 'thinking_level="high"' in publication\n    assert "GEMINI_LIGHT_MODEL" not in publication\n\n\ndef test_info_owner_refuses_stale_35_semantic_env(monkeypatch) -> None:\n    import services.livedub_info as info\n    monkeypatch.setenv("LIVEDUB_INFO_MODEL", "gemini-3.5-flash-lite")\n    monkeypatch.setenv("LIVEDUB_INFO_FALLBACK_MODELS", "gemini-3.5-flash")\n    assert info.get_light_model() == "gemini-3.6-flash"\n    assert info.get_light_model_fallbacks() == []\n\n\ndef test_info_card_tries_clients_without_mutating_registry(monkeypatch) -> None:\n    import services.livedub_info as info\n    calls = []\n    class Models:\n        def __init__(self, name, fail): self.name, self.fail = name, fail\n        async def generate_content(self, *, model, contents, config):\n            del contents\n            calls.append((self.name, model, config["thinking_level"]))\n            if self.fail: raise RuntimeError("unavailable")\n            return SimpleNamespace(text=json.dumps({"telegram_description":"Готово","youtube_title":"Название","youtube_description":"Описание","compact_subtitles":[],"hashtags":[],"key_theological_terms":[],"scripture_references":[]}, ensure_ascii=False))\n    class Client:\n        def __init__(self, name, fail): self.aio = SimpleNamespace(models=Models(name, fail))\n    clients = [Client("first", True), Client("second", False)]\n    monkeypatch.setattr(info, "GEMINI_CLIENTS", clients)\n    monkeypatch.setattr(info, "get_light_model", lambda: "gemini-3.6-flash")\n    monkeypatch.setattr(info, "get_light_model_fallbacks", lambda: [])\n    monkeypatch.setattr(info, "make_text_config_smart", lambda **kwargs: kwargs)\n    card = asyncio.run(info.build_livedub_info_card("Title", force=True))\n    assert card and calls == [("first", "gemini-3.6-flash", "high"), ("second", "gemini-3.6-flash", "high")]\n    assert info.GEMINI_CLIENTS is clients\n\n\ndef test_singleflight_failure_releases_retry_key() -> None:\n    delivery.reset_delivery_runtime_state()\n    key = ("new", "chat", "reply", "video")\n    attempts = 0\n    async def scenario():\n        nonlocal attempts\n        async def fail():\n            nonlocal attempts; attempts += 1; raise RuntimeError("telegram send failed")\n        async def succeed():\n            nonlocal attempts; attempts += 1; return True\n        with pytest.raises(RuntimeError, match="telegram send failed"):\n            await delivery._singleflight(key, fail)\n        assert key not in delivery._COMPANION_INFLIGHT\n        assert key not in delivery._COMPANION_SENT\n        assert await delivery._singleflight(key, succeed) is True\n    asyncio.run(scenario())\n    assert attempts == 2 and key in delivery._COMPANION_SENT\n\n\ndef test_singleflight_false_is_not_cached_and_concurrency_coalesces() -> None:\n    delivery.reset_delivery_runtime_state()\n    false_key = ("new", "chat", "reply", "false")\n    async def false_once(): return False\n    assert asyncio.run(delivery._singleflight(false_key, false_once)) is False\n    assert false_key not in delivery._COMPANION_SENT\n\n    key = ("new", "chat", "reply", "shared")\n    attempts = 0\n    async def scenario():\n        nonlocal attempts\n        started, release = asyncio.Event(), asyncio.Event()\n        async def sender():\n            nonlocal attempts; attempts += 1; started.set(); await release.wait(); return True\n        first = asyncio.create_task(delivery._singleflight(key, sender))\n        await started.wait()\n        second = asyncio.create_task(delivery._singleflight(key, sender))\n        await asyncio.sleep(0)\n        assert attempts == 1\n        release.set()\n        assert await asyncio.gather(first, second) == [True, True]\n    asyncio.run(scenario())\n    assert attempts == 1\n\n\ndef test_windows_media_probes_are_utf8_safe_at_source_owner() -> None:\n    companion = Path("services/livedub_audio_companion.py").read_text(encoding="utf-8")\n    mix = Path("services/livedub_mix.py").read_text(encoding="utf-8")\n    assert '"encoding": "utf-8"' in companion and '"errors": "replace"' in companion\n    assert '"encoding": "utf-8"' in mix and '"errors": "replace"' in mix\n''',
)

# 12) Companion unit tests cover helpers/cache and prove no Telegram interception remains.
write(
    "tests/test_livedub_audio_companion.py",
    '''from pathlib import Path\n\nimport services.livedub_audio_companion as companion\n\n\ndef test_livedub_caption_detection_is_narrow() -> None:\n    assert companion._is_livedub_caption("<b>Лекция</b>\\n🎬 Живые голоса Яндекса")\n    assert companion._is_livedub_caption("🎬 Перевод Яндекса (обычные голоса)")\n    assert not companion._is_livedub_caption("Обычное видео с русскими субтитрами")\n\n\ndef test_title_and_variant_filenames_are_human_readable(tmp_path: Path) -> None:\n    title, performer = companion._title_parts("<b>Как Мы Знаем? - Р. Ч. Спроул</b>", "fallback")\n    assert title == "Как Мы Знаем?" and performer == "Р. Ч. Спроул"\n    clean = companion._safe_filename(tmp_path / "pro_dub.mp4", title, "clean")\n    mixed = companion._safe_filename(tmp_path / "pro_dub.mp4", title, "mixed")\n    assert clean.endswith("чистый RU.mp3") and mixed.endswith("финальный микс.mp3")\n    assert clean != mixed and "?" not in clean and "?" not in mixed\n\n\ndef test_public_error_text_masks_bot_tokens_and_proxy_passwords() -> None:\n    token = "123456789:ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghi_123456"\n    public = companion._public_error_text(RuntimeError(f"https://api.telegram.org/bot{token}/sendAudio via http://user:secret@127.0.0.1:1080"), 500)\n    assert token not in public and "secret" not in public and "***" in public\n\n\ndef test_file_id_cache_stores_two_independent_variants(tmp_path: Path, monkeypatch) -> None:\n    cache_path = tmp_path / "audio-map.json"\n    monkeypatch.setattr(companion, "_cache_path", lambda: cache_path)\n    companion._cache_put_variant("video-1", "clean", "audio-clean", title="Title")\n    companion._cache_put_variant("video-1", "mixed", "audio-mixed", title="Title")\n    cached = companion._cache_get("video-1")\n    assert cached["variants"]["clean"]["audio_file_id"] == "audio-clean"\n    assert cached["variants"]["mixed"]["audio_file_id"] == "audio-mixed"\n    companion._cache_drop_variant("video-1", "clean")\n    assert "clean" not in companion._cache_get("video-1")["variants"]\n    companion._cache_drop("video-1")\n    assert companion._cache_get("video-1") is None\n\n\ndef test_companion_validator_does_not_install_telegram_wrappers() -> None:\n    source = Path("services/livedub_audio_companion.py").read_text(encoding="utf-8")\n    assert "_wrap_send_video" not in source\n    assert "Bot.send_video =" not in source\n    assert "ExtBot.send_video =" not in source\n    assert "explicit coordinator delivery" in companion.validate_livedub_audio_companion()\n''',
)

# 13) Audio quality tests role selection and explicit coordinator fail-closed behavior.
write(
    "tests/test_livedub_audio_quality_guard.py",
    '''from __future__ import annotations\n\nimport asyncio\nimport os\nfrom pathlib import Path\n\nimport pytest\n\nfrom services import livedub_audio_companion as companion\nfrom services import livedub_audio_quality_guard as guard\nfrom services import livedub_delivery_coordinator as delivery\nfrom services.runtime_manifest import DEFAULT_RUNTIME_FEATURES\n\n\ndef test_clean_selector_ignores_newer_derived_mp3s(tmp_path: Path) -> None:\n    clean = tmp_path / "translation.live.mp3"; clean.write_bytes(b"clean" * 400)\n    mixed = tmp_path / "sermon.final-mix.mp3"; mixed.write_bytes(b"mixed" * 400)\n    legacy = tmp_path / "sermon.ru-audio.mp3"; legacy.write_bytes(b"legacy" * 400)\n    os.utime(clean, (10, 10)); os.utime(mixed, (30, 30)); os.utime(legacy, (20, 20))\n    assert guard.is_derived_audio_artifact(mixed) and guard.is_derived_audio_artifact(legacy)\n    assert guard.select_clean_translation_mp3(tmp_path) == clean\n\n\ndef test_clean_selector_rejects_qa_and_original_audio(tmp_path: Path) -> None:\n    (tmp_path / "original_audio.mp3").write_bytes(b"original" * 300)\n    (tmp_path / "translation_qa.mp3").write_bytes(b"qa" * 700)\n    assert guard.select_clean_translation_mp3(tmp_path) is None\n\n\ndef test_dual_delivery_fails_closed_when_clean_track_missing(monkeypatch, tmp_path: Path) -> None:\n    video = tmp_path / "final.mp4"; video.write_bytes(b"video" * 400)\n    mixed = tmp_path / "final.final-mix.mp3"; mixed.write_bytes(b"mixed" * 400)\n    monkeypatch.setattr(companion, "_dual_enabled", lambda: True)\n    monkeypatch.setattr(companion, "_probe_audio", lambda _path: (True, 120))\n    monkeypatch.setattr(guard, "select_clean_translation_mp3", lambda _path: None)\n    monkeypatch.setattr(companion, "_extract_mix_mp3", lambda _path: mixed)\n    with pytest.raises(RuntimeError, match="чистая русская дорожка не найдена"):\n        asyncio.run(delivery.deliver_new_companions(object(), chat_id=1, video_path=video, publication_card={}, reply_to=2, thumbnail=None, video_file_id="video-id"))\n\n\ndef test_dual_delivery_rejects_same_physical_file_for_both_roles(monkeypatch, tmp_path: Path) -> None:\n    video = tmp_path / "final.mp4"; video.write_bytes(b"video" * 400)\n    shared = tmp_path / "translation.live.mp3"; shared.write_bytes(b"audio" * 400)\n    monkeypatch.setattr(companion, "_dual_enabled", lambda: True)\n    monkeypatch.setattr(companion, "_probe_audio", lambda _path: (True, 120))\n    monkeypatch.setattr(guard, "select_clean_translation_mp3", lambda _path: shared)\n    monkeypatch.setattr(companion, "_extract_mix_mp3", lambda _path: shared)\n    with pytest.raises(RuntimeError, match="один файл"):\n        asyncio.run(delivery.deliver_new_companions(object(), chat_id=1, video_path=video, publication_card={}, reply_to=2, thumbnail=None, video_file_id="video-id"))\n\n\ndef test_mix_and_vot_use_source_owned_clean_selector(tmp_path: Path) -> None:\n    from services import livedub_mix as mix\n    from services import yandex_live_dub as yandex\n    clean = tmp_path / "translation.live.mp3"; clean.write_bytes(b"clean" * 400)\n    stale = tmp_path / "translation.final-mix.mp3"; stale.write_bytes(b"mixed" * 400)\n    os.utime(clean, (10, 10)); os.utime(stale, (20, 20))\n    assert mix.find_pro_tracks(tmp_path)[1] == clean\n    assert yandex._find_latest_file(tmp_path, "*.mp3") == clean\n\n\ndef test_manifest_uses_delivery_contract_not_quality_installers() -> None:\n    ids = {feature.feature_id for feature in DEFAULT_RUNTIME_FEATURES}\n    assert "livedub-delivery-contract" in ids\n    assert "livedub-audio-quality" not in ids\n    assert "livedub-audio-dedupe" not in ids\n''',
)

