write(
    "tests/test_livedub_qa_reporting_hardening.py",
    '''from pathlib import Path\n\nfrom services import livedub_qa_hardening as qa\n\n\ndef test_notes_are_inserted_after_report_heading() -> None:\n    assert qa._insert_after_head("HEAD\\nBODY", ["NOTE 1", "NOTE 2"]) == "HEAD\\nNOTE 1\\nNOTE 2\\nBODY"\n\n\ndef test_annotate_availability_tracks_original_and_russian_separately(tmp_path: Path) -> None:\n    original = tmp_path / "original.mp3"; original.write_bytes(b"original")\n    russian = tmp_path / "dub.mp3"; russian.write_bytes(b"russian")\n    data = qa.annotate_qa_availability({}, {"original_audio_path": original, "dub_audio_path": russian, "dub_video_path": russian, "existing_audio_part": None, "existing_client": None}, None)\n    assert data["_qa_original_reference_available"] is True\n    assert data["_qa_local_original_available"] is True\n    assert data["_qa_russian_audio_available"] is True\n\n\ndef test_exact_uncut_original_replaces_edited_reference(monkeypatch, tmp_path: Path) -> None:\n    exact = tmp_path / "original_video.mp4"; exact.write_bytes(b"video")\n    monkeypatch.setattr(qa, "_exact_original_in_workdir", lambda _value: exact)\n    prepared, found = qa.prepare_exact_timeline_inputs({"dub_video_path": tmp_path / "dub.mp4", "original_audio_path": tmp_path / "edited.mp3", "existing_audio_part": object(), "existing_client": object()})\n    assert found == exact\n    assert prepared["original_audio_path"] == exact\n    assert prepared["existing_audio_part"] is None\n    assert prepared["existing_client"] is None\n\n\ndef test_hardened_report_marks_unverified_limit_without_publishing_candidates() -> None:\n    rendered = qa.decorate_hardened_report("HEAD\\nBODY", {"issues": [], "_qa_verification_limit_dropped": 3})\n    assert "За пределами настроенного лимита осталось замечаний: 3" in rendered\n    assert "они не опубликованы" in rendered\n\n\ndef test_one_validation_issue_cannot_confirm_two_primary_findings() -> None:\n    primary = {"issues": [{"time":"00:10","heard":"same important phrase","problem":"wrong meaning"}, {"time":"00:11","heard":"same important phrase","problem":"wrong meaning"}]}\n    validation = {"issues": [{"time":"00:10","heard":"same important phrase","problem":"wrong meaning"}]}\n    result = qa.confirmed_result_one_to_one(primary, validation)\n    assert len(result["issues"]) == 1\n''',
)

# 15) Shorts visual policy is PRE_MAIN through the manifest, not services import side effects.
path = "tests/test_shorts_static_runtime.py"
text = read(path)
pattern = r'def test_installation_precedes_shorts_import_contract\(\) -> None:.*\Z'
replacement = '''def test_manifest_owns_shorts_visual_policy_before_main_import() -> None:\n    init_source = (ROOT / "services" / "__init__.py").read_text(encoding="utf-8")\n    manifest_source = (ROOT / "services" / "runtime_manifest.py").read_text(encoding="utf-8")\n    assert "install_short_static_runtime()" not in init_source\n    assert '"shorts-visual-policy"' in manifest_source\n    assert '"services.shorts_static_runtime"' in manifest_source\n    runtime_source = (ROOT / "services" / "shorts_static_runtime.py").read_text(encoding="utf-8")\n    assert "moving=crop_zoom" in runtime_source\n    assert "SHORTS_STATIC_SECOND_PROBE_OFFSET" in runtime_source\n    assert "await run_cancellable_process(" in runtime_source\n    assert "run_in_executor" not in runtime_source\n    assert "subprocess.run(" not in runtime_source\n'''
text, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
if count != 1:
    raise SystemExit(f"shorts policy test replacement count={count}")
write(path, text)

# 16) Old manifest-order assertions in otherwise-valid atomicity/deep-audit suites.
for path, func_name, replacement in (
    (
        "tests/test_livedub_cached_delivery_atomicity.py",
        "test_manifest_keeps_cached_transaction_before_capturing_wrappers",
        '''def test_manifest_uses_single_explicit_cached_delivery_contract():\n    ids = {feature.feature_id for feature in DEFAULT_RUNTIME_FEATURES}\n    assert "livedub-delivery-contract" in ids\n    assert "livedub-cached-delivery-atomicity" not in ids\n    assert "livedub-audio-dedupe" not in ids\n''',
    ),
    (
        "tests/test_livedub_deep_audit.py",
        "test_manifest_installs_deep_audit_after_dedupe_before_hardening",
        '''def test_manifest_uses_source_owned_livedub_contracts_before_project_hardening():\n    order = {feature.feature_id: index for index, feature in enumerate(DEFAULT_RUNTIME_FEATURES)}\n    assert order["livedub-qa-contract"] < order["project-runtime-hardening"]\n    assert order["livedub-delivery-contract"] < order["project-runtime-hardening"]\n    assert "livedub-deep-audit" not in order\n    assert "livedub-audio-dedupe" not in order\n''',
    ),
):
    text = read(path)
    pattern = rf'def {func_name}\(\):.*?(?=\ndef |\Z)'
    text, count = re.subn(pattern, replacement.rstrip() + "\n", text, count=1, flags=re.S)
    if count != 1:
        raise SystemExit(f"{path}:{func_name} replacement count={count}")
    write(path, text)

